private List<Pair<List<Pair<Integer, Integer>>, E>> computeLocalSeparatorList(E edge) {
    List<Pair<List<Pair<Integer, Integer>>, E>> result = new ArrayList<>();
    for (V vertex : G.getNeighborhood(edge.getv())) {
        for (Edge incidentEdge : G.getAdjacency(vertex)) {
            List<Pair<Integer, Integer>> separator = computeSeparator(edge, incidentEdge);
            result.add(new Pair<List<Pair<Integer, Integer>>, E>(separator, incidentEdge));
        }
    }
