    // Check if the graph is complete
    if (graph.vertices().size() != vertices.size()) {
        return false;
    }

    // Check if the subgraph is a clique
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.adjacencySetMap().containsKey(v1) || !graph.adjacencySetMap().get(v1).contains(v2)) {
                return false;
            }
        }
    }

    return true;
}

