public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

	try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
		String line;
		while ((line = reader.readLine()) != null) {
			if (line.startsWith("Thread ID")) {
				ThreadSnapshot threadSnapshot = parseThreadSnapshotLine(line, timeRanges);
				threadSnapshots.add(threadSnapshot);
			}
		}
	} catch (IOException e) {
		throw e;
	}

	return threadSnapshots;
}

private static ThreadSnapshot parseThreadSnapshotLine(String line, List<ProfileAnalyzeTimeRange> timeRanges) {
	String[] tokens = line.split("\\s+");
	long threadId = Long.parseLong(tokens[1]);
	int saCount = Integer.parseInt(tokens[2]);
	int completedCallsCount = Integer.parseInt(tokens[3]);

	ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId);
	threadSnapshot.setStackTraceSequence(parseStackTraceSequence(line, saCount));
	threadSnapshot.setEvents(parseCallEvents(line, completedCallsCount));
	threadSnapshot.setTimeRanges(timeRanges);

	return threadSnapshot;
}
